import Base

def result(value: CompilerRows(U32) & U32) -> U32:
  match value:
    case Tuple{rows, word}: word

def duplicate(rows: CompilerRows(U32)) -> U32:
  U32.add(result(CompilerRows.get(U32, rows, 0)), result(CompilerRows.get(U32, rows, 0)))

def main() -> U32:
  duplicate(CompilerRows.new(U32, 0n, 0))

